/**
 * Minimal Thai "shaping" for LVGL (which has no OpenType layout):
 * a tone mark (U+0E48..0E4C) that follows an upper vowel / mai han-akat /
 * nikhahit, or that precedes sara am (U+0E33), is replaced by a raised copy
 * at U+F700..F704 (generated by tools/ttf2lvgl.py), so it no longer collides.
 *   e.g. "ที่", "เริ่ม", "เพื่อ", "ต่ำ", "น้ำ"
 */
#ifndef THAI_TEXT_H
#define THAI_TEXT_H

#include <stddef.h>
#include "lvgl.h"

size_t thai_shape(const char *in, char *out, size_t out_size);
void   thai_label_set_text(lv_obj_t *label, const char *txt);
void   thai_label_set_fmt(lv_obj_t *label, const char *fmt, ...);

#endif /* THAI_TEXT_H */
